<?php if(!defined('ABSPATH'))exit; ?><!doctype html><html <?php language_attributes(); ?>><head><meta charset="<?php bloginfo('charset'); ?>"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php the_title(); ?> · <?php bloginfo('name'); ?></title><?php wp_head(); ?></head><body <?php body_class(); ?>><?php wp_body_open(); ?><header class="header"><div class="container"><a class="brand" href="<?php echo esc_url(home_url('/')); ?>"><?php bloginfo('name'); ?></a><nav class="nav"><a href="<?php echo esc_url(home_url('/')); ?>">Home</a></nav></div></header><main class="stories"><div class="container"><?php while(have_posts()):the_post(); ?><article class="single-post"><div class="kicker"><?php $cats=get_the_category();if($cats)echo esc_html($cats[0]->name); ?></div><h1><?php the_title(); ?></h1><div class="date"><?php echo esc_html(get_the_date('F j, Y')); ?> · <?php echo esc_html(get_the_author()); ?></div><?php if(has_post_thumbnail())the_post_thumbnail('large',array('class'=>'featured-image')); ?><div class="entry-content"><?php the_content(); ?></div><div class="post-tags"><?php the_tags('Tags: ', ' · ', ''); ?></div></article><?php endwhile; ?></div></main><footer class="footer"><div class="container">© <?php echo date('Y'); ?> <?php bloginfo('name'); ?></div></footer><?php wp_footer(); ?></body></html>